/**
 * AI action registry — types.
 *
 * Generated by slice S1 of the TManage AI connector (MCP). See
 * `MCP-CONNECTOR-PLAN-2026-10-20.md` §2, §7 (S1) and
 * `MCP-CONNECTOR-ARCHITECTURE-2026-10-20.md` B3 / T-REG-01.
 *
 * This is the route *inventory and classification skeleton*. Every one of the
 * 710 live API routes is accounted for exactly once: either as an op here or as
 * a `NEVER` deny-list entry. `registry-sync.test.ts` enumerates the live routes
 * by reflection and fails if any route is unclassified, double-classified, or
 * carries a capability that disagrees with its op. Slices S2–S4 add the zod
 * input/output schemas, redaction profiles, titles, descriptions and examples
 * to each op; this slice fixes only id, method, path, capability, risk and scope.
 */
import type { Capability } from '@tmanage/domain';

/** HTTP methods the API actually serves (no ALL/OPTIONS/HEAD among the 710 routes). */
export const HTTP_METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'] as const;
export type HttpMethod = (typeof HTTP_METHODS)[number];

/**
 * Risk class of an AI-exposable op (plan §2).
 * - `read`    — a read; runs at once under the `read` scope.
 * - `write`   — an ordinary edit within the member's own rights; runs at once under `write`.
 * - `confirm` — needs a human approval outside the model (plan §4.3) before it runs.
 * A fourth class, "never", is not a risk but the absence of an op: those routes live in `NEVER`.
 */
export const RISK_CLASSES = ['read', 'write', 'confirm'] as const;
export type RiskClass = (typeof RISK_CLASSES)[number];

/**
 * 62-11 (plan 62 §4.3). What a change touches, which decides its gate in the in-app AI: `money`
 * and `hr` need a step-up, a typed amount and the workspace's approval rule; `external` and
 * `destructive` always show a card; `none` is an everyday change. Every op that is not `read`
 * carries one in `sensitivity.ts` (required by `registry-sync.test.ts`).
 */
export const SENSITIVITIES = ['money', 'hr', 'external', 'destructive', 'none'] as const;
export type Sensitivity = (typeof SENSITIVITIES)[number];

/** Consent scopes (plan §4.2). A scope only ever *narrows* access. */
export const AI_SCOPES = ['read', 'write', 'manage', 'billing'] as const;
export type AiScope = (typeof AI_SCOPES)[number];

