/**
 * A single AI-exposable operation. S1 populates the classification fields only;
 * S2–S4 add the schema/redaction/presentation fields (kept optional here so the
 * skeleton type-checks before those slices land).
 */
export interface AiActionOp {
  /** Stable registry id, e.g. `work.item.create`. Never a path — `run_action` takes this id. */
  readonly id: string;
  readonly method: HttpMethod;
  /** The Nest route path, including `:params` — the key the sync test matches against. */
  readonly path: string;
  /** The route's `@RequireCapability`, mirrored here so the sync test can detect drift. */
  readonly capability: Capability | null;
  readonly risk: RiskClass;
  readonly scope: AiScope;
  /**
   * Audit run 2, N07. A `write` op that becomes confirm-class for one call when its arguments
   * reach a client (a client-audience work item, a client attendee). Both channels — the REST
   * bound-token interceptor and the MCP runtime — treat a matching call exactly like a `confirm`
   * op; a call that does not match stays an everyday write. See {@link callNeedsConfirm}.
   */
  readonly confirmWhen?: ConfirmWhen;
  /**
   * Audit run 3, M01. A `write` op on an existing row that becomes confirm-class for one call when
   * the row it changes is already client-facing — renaming, re-dating or moving a work item the
   * client already sees is a client-facing change even when the call names no audience. Read from
   * stored state by {@link callNeedsConfirmWithState}, never from the call's arguments.
   */
  readonly confirmWhenStored?: ConfirmWhenStored;
}

/**
 * A "this call is confirm-class when the stored row matches" rule (M01). `param` names the path
 * argument carrying the row id; the row's `field` is looked up tenant-scoped, and a value outside
 * `notIn` makes the call confirm-class.
 */
export interface ConfirmWhenStored {
  readonly resource: 'work_item';
  readonly param: 'workItemId';
  readonly field: 'audience';
  readonly notIn: readonly ['internal'];
}

/**
 * Reads one stored field of one row, tenant-scoped (the caller binds the organization). Resolves
 * `undefined` when the row does not exist or is not readable.
 */
export type StoredFieldLookup = (
  resource: ConfirmWhenStored['resource'],
  id: string,
  field: ConfirmWhenStored['field'],
) => Promise<string | undefined>;

/**
 * A declarative "this call is confirm-class when the body matches" rule, read from the call's own
 * arguments (path params plus the body) — never from stored state.
 * - `present: true` — matches when `field` is sent at all (any value other than `undefined`).
 * - `notIn` — matches when `field` is sent with a value outside the list (an absent field takes the
 *   server default, which must be one of the listed values). A value that is not a listed string,
 *   `null` included, matches: an unrecognised value fails closed.
 */
export interface ConfirmWhen {
  readonly field: string;
  readonly notIn?: readonly string[];
  readonly present?: true;
}

/** Whether one call of `op` with these arguments needs a person's approval before it runs. */
export function callNeedsConfirm(op: AiActionOp, args: Readonly<Record<string, unknown>>): boolean {
  if (op.risk === 'confirm') return true;
  const rule = op.confirmWhen;
  if (rule === undefined) return false;
  const value = Object.prototype.hasOwnProperty.call(args, rule.field)
    ? args[rule.field]
    : undefined;
  if (value === undefined) return false;
  if (rule.present === true) return true;
  if (rule.notIn !== undefined) return typeof value !== 'string' || !rule.notIn.includes(value);
  // A rule naming neither condition is malformed; treat any sent value as confirm-class.
  return true;
}

/**
 * {@link callNeedsConfirm}, plus the stored-state rule (M01): also `true` when the op carries
 * `confirmWhenStored` and the stored row's field is outside `notIn`. A missing id, a missing row,
 * or no `lookup` gives `false` for the stored rule — the handler answers 404 for a row that does
 * not exist, so nothing client-facing can happen on that path. A lookup that **throws** gives
 * `true` (R4-01, wave 12): the stored state is unknown, so the call needs approval (fail closed).
 */
export async function callNeedsConfirmWithState(
  op: AiActionOp,
  args: Readonly<Record<string, unknown>>,
  lookup: StoredFieldLookup | undefined,
): Promise<boolean> {
  if (callNeedsConfirm(op, args)) return true;
  const rule = op.confirmWhenStored;
  if (rule === undefined || lookup === undefined) return false;
  const id = Object.prototype.hasOwnProperty.call(args, rule.param) ? args[rule.param] : undefined;
  if (typeof id !== 'string' || id === '') return false;
  let stored: string | undefined;
  try {
    stored = await lookup(rule.resource, id, rule.field);
  } catch {
    // R4-01: an unreadable row is not a row known to be internal - fail closed.
    return true;
  }
  if (typeof stored !== 'string') return false;
  return !(rule.notIn as readonly string[]).includes(stored);
}

/** A route withheld from the AI surface (architecture B3 deny-list). */
export interface NeverEntry {
  readonly method: HttpMethod;
  readonly path: string;
  readonly reason: NeverReason;
}

/** The canonical key for a route: `"<METHOD> <path>"`. */
export type RouteKey = `${HttpMethod} ${string}`;

export function routeKey(method: string, path: string): RouteKey {
  return `${method.toUpperCase()} ${path}` as RouteKey;
}
